function getHeyGenTranslation(key, lang) {
    if (heygenTranslations[lang] && heygenTranslations[lang][key]) {
        return heygenTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (heygenTranslations.en && heygenTranslations.en[key]) {
        return heygenTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions heygen
function applyHeyGenTranslations(lang) {
    console.log('🔥 Applying heygen translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés heygen
        if (key && (key.startsWith('review.heygen.') || key.startsWith('review.common.'))) {
            const translation = getHeyGenTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} heygen translations`);
}

// Auto-appliquer quand la langue change
document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyHeyGenTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyHeyGenTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyHeyGenTranslations(currentLang);
}

console.log('✅ heygen i18n loaded');
